const item = $input.first().json;
const now = new Date().toISOString();

item.logs = Array.isArray(item.logs) ? item.logs : [];

function cleanText(value) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .trim();
}

function cleanLongText(value) {
  return String(value || "")
    .replace(/\r/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function simpleHash(input) {
  let hash = 0;
  const str = String(input || "");

  for (let i = 0; i < str.length; i++) {
    const chr = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + chr;
    hash |= 0;
  }

  return Math.abs(hash).toString(16);
}

function getCandidateJobs(item) {
  const sources = [
    item.jobs_input,
    item.raw_jobs,
    item.jobs,
    item.normalized_jobs
  ];

  for (const source of sources) {
    if (Array.isArray(source) && source.length > 0) {
      return source;
    }
  }

  return [];
}

const candidateJobs = getCandidateJobs(item);

const normalizedJobs = candidateJobs
  .map((job, index) => {
    const company = cleanText(job.company || job.company_name || job.organization || "");
    const title = cleanText(job.title || job.job_title || job.position || "");
    const location = cleanText(job.location || job.job_location || "Not listed");
    const employmentType = cleanText(job.employment_type || job.type || "Not listed");
    const jobUrl = cleanText(job.job_url || job.url || job.apply_url || "");
    const applyUrl = cleanText(job.apply_url || job.job_url || job.url || "");
    const description = cleanLongText(job.description || job.job_description || job.summary || "");
    const salary = cleanText(job.salary || "Not listed");
    const source = cleanText(job.source || "manual_input");

    const baseHash = job.job_hash || `${source}_${simpleHash(`${company}|${title}|${jobUrl || index}`)}`;

    return {
      run_id: item.run_id || "",
      job_hash: baseHash,
      date_found: cleanText(job.date_found || now),
      source,
      company,
      title,
      location,
      employment_type: employmentType,
      job_url: jobUrl,
      apply_url: applyUrl,
      date_posted: cleanText(job.date_posted || "manual_input"),
      description,
      salary,
      raw_json: job.raw_json || job,
      duplicate_status: cleanText(job.duplicate_status || "new"),
      hard_filter_status: cleanText(job.hard_filter_status || "pending")
    };
  })
  .filter(job => {
    return job.company && job.title && job.description && job.description.length >= 30;
  });

item.jobs_input = normalizedJobs;
item.raw_jobs = normalizedJobs;
item.jobs = normalizedJobs;
item.normalized_jobs = normalizedJobs;

item.logs.push({
  run_id: item.run_id,
  timestamp: now,
  node_name: "Normalize Job Data",
  status: "success",
  message: `Normalized ${normalizedJobs.length} jobs.`,
  cost_control_note: "Normalization reads manual, sample, External Job Feed, raw_jobs, jobs, jobs_input, or normalized_jobs. No paid API call.",
  error_detail: normalizedJobs.length === 0
    ? JSON.stringify({
        available_arrays: {
          jobs_input: Array.isArray(item.jobs_input) ? item.jobs_input.length : "not_array",
          raw_jobs: Array.isArray(item.raw_jobs) ? item.raw_jobs.length : "not_array",
          jobs: Array.isArray(item.jobs) ? item.jobs.length : "not_array",
          normalized_jobs: Array.isArray(item.normalized_jobs) ? item.normalized_jobs.length : "not_array"
        }
      })
    : ""
});

return [{ json: item }];

const item = $input.first().json;
const now = new Date().toISOString();

item.logs = Array.isArray(item.logs) ? item.logs : [];

const config = item.config || {};
const inputJobs = Array.isArray(item.normalized_jobs) && item.normalized_jobs.length > 0
  ? item.normalized_jobs
  : Array.isArray(item.jobs_input) && item.jobs_input.length > 0
    ? item.jobs_input
    : Array.isArray(item.jobs) && item.jobs.length > 0
      ? item.jobs
      : Array.isArray(item.raw_jobs) && item.raw_jobs.length > 0
        ? item.raw_jobs
        : [];

function cleanText(value) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeForKey(value) {
  return cleanText(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function isManualJob(job) {
  const source = cleanText(job.source).toLowerCase();
  return (
    config.job_input_mode === "manual" ||
    source.includes("manual")
  );
}

function detectCptRisk(job) {
  const combined = `${job.title || ""} ${job.employment_type || ""} ${job.description || ""}`.toLowerCase();

  const riskReasons = [];

  if (combined.includes("full-time") || combined.includes("full time")) {
    riskReasons.push("full_time_role");
  }

  if (!combined.includes("intern") && !combined.includes("internship")) {
    riskReasons.push("not_internship");
  }

  if (
    combined.includes("us citizen") ||
    combined.includes("u.s. citizen") ||
    combined.includes("citizenship required") ||
    combined.includes("security clearance")
  ) {
    riskReasons.push("possible_work_authorization_restriction");
  }

  return {
    cpt_risk: riskReasons.length > 0 ? "review_required" : "low",
    cpt_review_required: riskReasons.length > 0,
    cpt_risk_reasons: riskReasons
  };
}

function hasExcludedKeyword(job) {
  const combined = `${job.title || ""} ${job.description || ""}`.toLowerCase();
  const excluded = Array.isArray(config.excluded_keywords) ? config.excluded_keywords : [];

  const found = excluded.filter(keyword => {
    const k = String(keyword || "").toLowerCase().trim();
    if (!k) return false;
    return combined.includes(k);
  });

  return found;
}

function isRelevantRole(job) {
  const combined = `${job.title || ""} ${job.description || ""}`.toLowerCase();

  const relevantTerms = [
    "hr",
    "human resources",
    "people",
    "talent",
    "recruit",
    "onboarding",
    "employee",
    "workforce",
    "benefits",
    "compensation",
    "total rewards",
    "hris",
    "operations",
    "people analytics",
    "human resources operations",
    "associate experience",
    "talent management"
  ];

  return relevantTerms.some(term => combined.includes(term));
}

const seen = new Set();
const filteredJobs = [];
const rejectedJobs = [];

inputJobs.forEach(job => {
  const company = cleanText(job.company);
  const title = cleanText(job.title);
  const jobUrl = cleanText(job.job_url || job.apply_url);
  const description = cleanText(job.description);

  const key = normalizeForKey(`${company}|${title}|${jobUrl}`);

  const cptInfo = detectCptRisk(job);
  const manual = isManualJob(job);
  const excludedFound = hasExcludedKeyword(job);
  const relevant = isRelevantRole(job);

  const enrichedJob = {
    ...job,
    company,
    title,
    job_url: jobUrl,
    apply_url: cleanText(job.apply_url || jobUrl),
    description,
    duplicate_status: "new",
    hard_filter_status: "passed",
    cpt_risk: cptInfo.cpt_risk,
    cpt_review_required: cptInfo.cpt_review_required,
    cpt_risk_reasons: cptInfo.cpt_risk_reasons
  };

  if (!company || !title || !description) {
    enrichedJob.hard_filter_status = "rejected_missing_required_data";
    rejectedJobs.push(enrichedJob);
    return;
  }

  if (seen.has(key)) {
    enrichedJob.duplicate_status = "duplicate";
    enrichedJob.hard_filter_status = "rejected_duplicate";
    rejectedJobs.push(enrichedJob);
    return;
  }

  seen.add(key);

  // Manual mode safety:
  // Do not reject a manually pasted job just because it is full-time or not perfect.
  // Let it pass, but mark work authorization/work authorization review if needed.
  if (manual) {
    enrichedJob.hard_filter_status = cptInfo.cpt_review_required
      ? "passed_manual_review_required"
      : "passed_manual";
    filteredJobs.push(enrichedJob);
    return;
  }

  // For External Job Feed/sample automated jobs, keep stricter filtering.
  if (excludedFound.length > 0) {
    enrichedJob.hard_filter_status = `rejected_excluded_keywords_${excludedFound.join("_")}`;
    rejectedJobs.push(enrichedJob);
    return;
  }

  if (!relevant) {
    enrichedJob.hard_filter_status = "rejected_role_not_relevant";
    rejectedJobs.push(enrichedJob);
    return;
  }

  filteredJobs.push(enrichedJob);
});

