function cleanText(value) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .trim();
}

function uniqueArray(values) {
  return [...new Set((values || []).filter(Boolean))];
}

function lowerText(value) {
  return cleanText(value).toLowerCase();
}

function includesAny(text, terms) {
  const t = lowerText(text);
  return (terms || []).some(term => t.includes(lowerText(term)));
}

function findKeywordHits(text, keywords) {
  const t = lowerText(text);
  return uniqueArray((keywords || []).filter(keyword => {
    const k = lowerText(keyword);
    return k && t.includes(k);
  }));
}

function clampScore(value) {
  const n = Math.round(Number(value || 0));
  return Math.max(0, Math.min(100, n));
}

function detectResumeAngle(jobText) {
  const text = lowerText(jobText);

  const angleProfiles = factBank.angle_profiles || {};

  const scores = {
    people_analytics: countHits(text, angleProfiles.people_analytics || [
      "people analytics", "hr reporting", "power bi", "tableau", "python", "dashboard", "analytics", "workforce"
    ]),
    hr_operations: countHits(text, angleProfiles.hr_operations || [
      "hr operations", "onboarding", "employee records", "hr documentation", "employee lifecycle", "associate experience"
    ]),
    recruiting_coordination: countHits(text, angleProfiles.recruiting_coordination || [
      "recruitment", "talent acquisition", "candidate", "interview", "new hire"
    ]),
    total_rewards: countHits(text, angleProfiles.total_rewards || [
      "benefits", "compensation", "total rewards", "open enrollment", "payroll"
    ]),
    hris_operations: countHits(text, angleProfiles.hris_operations || [
      "hris", "systems administration", "workflow", "sharepoint", "employee records", "process improvement"
    ])
  };

  const sorted = Object.entries(scores).sort((a, b) => b[1] - a[1]);

  if (sorted[0] && sorted[0][1] > 0) {
    return sorted[0][0];
  }

  if (text.includes("hr") || text.includes("human resources") || text.includes("people")) {
    return "hr_operations";
  }

  return "general_hr";
}

function countHits(text, terms) {
  return (terms || []).reduce((count, term) => {
    return text.includes(lowerText(term)) ? count + 1 : count;
  }, 0);
}

function calculateRoleRelevance(jobText) {
  const strongTerms = [
    "human resources",
    "hr operations",
    "people operations",
    "people analytics",
    "talent acquisition",
    "recruitment",
    "onboarding",
    "employee records",
    "employee lifecycle",
    "hris",
    "benefits",
    "compensation",
    "total rewards",
    "associate experience",
    "talent management",
    "hr systems"
  ];

  const hits = countHits(lowerText(jobText), strongTerms);

  if (hits >= 7) return 90;
  if (hits >= 5) return 82;
  if (hits >= 3) return 75;
  if (hits >= 2) return 67;
  if (hits >= 1) return 58;
  return 40;
}

function calculateInternshipFit(job) {
  const combined = lowerText(`${job.title || ""} ${job.employment_type || ""} ${job.description || ""}`);

  if (combined.includes("internship") || combined.includes("intern ")) return 92;
  if (combined.includes("entry level") || combined.includes("entry-level") || combined.includes("coordinator")) return 70;
  if (combined.includes("associate")) return 62;
  if (combined.includes("full-time") || combined.includes("full time")) return 55;

  return 60;
}

function calculateSkillsMatch(jobText) {
  const approvedSkills = factBank.approved_skills || [];
  const preferredKeywords = config.preferred_keywords || [];

  const approvedHits = findKeywordHits(jobText, approvedSkills);
  const preferredHits = findKeywordHits(jobText, preferredKeywords);

  const totalHits = uniqueArray([...approvedHits, ...preferredHits]);

  let score = 45 + (totalHits.length * 6);

  if (includesAny(jobText, ["excel", "advanced excel"])) score += 6;
  if (includesAny(jobText, ["hris", "hr systems", "systems administration"])) score += 8;
  if (includesAny(jobText, ["onboarding", "offboarding"])) score += 8;
  if (includesAny(jobText, ["employee records", "documentation"])) score += 7;
  if (includesAny(jobText, ["data", "reporting", "analytics", "dashboard"])) score += 8;

  return clampScore(score);
}

function calculateCptFit(job) {
  if (job.cpt_review_required === true) return 60;

  const combined = lowerText(`${job.title || ""} ${job.employment_type || ""} ${job.description || ""}`);

  if (combined.includes("internship") || combined.includes("intern ")) return 90;
  if (combined.includes("part-time") || combined.includes("part time")) return 78;
  if (combined.includes("full-time") || combined.includes("full time")) return 60;

  return 70;
}

function calculateCompanyStrength(job) {
  const company = lowerText(job.company);
  const tierCompanies = (config.company_tier_keywords || []).map(lowerText);

  if (tierCompanies.some(c => company.includes(c))) return 90;

  const description = lowerText(job.description);

  if (description.includes("vendor") || description.includes("partners") || description.includes("programs")) return 72;

  return 65;
}

function calculateLocationTimingFit(job) {
  const location = lowerText(job.location);

  if (!location || location === "not listed") return 65;
  if (location.includes("remote")) return 85;
  if (location.includes("nj") || location.includes("new jersey")) return 88;
  if (location.includes("ny") || location.includes("new york")) return 82;
  if (location.includes("pa") || location.includes("pennsylvania")) return 80;

  return 68;
}

function calculateNetworkingPotential(job) {
  const company = lowerText(job.company);
  const description = lowerText(job.description);

  let score = 55;

  if (company) score += 5;
  if (description.includes("human resources") || description.includes("people")) score += 8;
  if (description.includes("talent") || description.includes("recruit")) score += 6;
  if (description.includes("associate experience") || description.includes("hr operations")) score += 6;

  return clampScore(score);
}

function calculateApplicationEase(job) {
  if (job.apply_url || job.job_url) return 85;
  return 55;
}

function detectMissingRequirements(jobText) {
  const missing = [];

  if (!includesAny(jobText, ["excel", "advanced excel"])) {
    missing.push("Excel not explicit in job description.");
  }

  if (!includesAny(jobText, ["power bi", "tableau", "dashboard", "analytics", "reporting"])) {
    missing.push("Analytics/dashboard language is limited in the job description.");
  }

  if (!includesAny(jobText, ["intern", "internship"])) {
    missing.push("Role is not listed as an internship. Review work authorization fit before applying.");
  }

  return missing;
}

function getPriorityLabel(score) {
  if (score >= 85) return "A - apply now";
  if (score >= 70) return "B - good fit";
  if (score >= 50) return "C - review";
  return "D - save only";
}

function getRecommendation(score, job) {
  if (score < 50) return "save_only";
  if (job.cpt_review_required === true && score < 70) return "resume_for_review";
  if (score >= 85) return "apply_now";
  if (score >= 70) return "apply_after_review";
  return "resume_for_review";
}

function shouldCreateResume(score) {
  return score >= 50;
}

function shouldCreateContacts(score) {
  return score >= 50;
}

function shouldCreateCoverLetter(score) {
  return score >= 60;
}

function makeMatchReason(keywordHits, score, angle) {
  const hitsText = keywordHits.length > 0
