    cleanText(row.linkedin_url || row.source_url).toLowerCase()
  ].join("|");
}

function dedupeContacts(rows) {
  const map = new Map();

  ensureArray(rows).forEach(row => {
    const key = contactKey(row);
    if (!key || key.replace(/\|/g, "").trim() === "") return;

    const existing = map.get(key);

    if (!existing) {
      map.set(key, row);
      return;
    }

    const currentScore = Number(row.relevance_score || 0);
    const existingScore = Number(existing.relevance_score || 0);

    if (currentScore > existingScore) {
      map.set(key, row);
    }
  });

  return Array.from(map.values()).sort((a, b) => {
    return Number(b.relevance_score || 0) - Number(a.relevance_score || 0);
  });
}

function jobKey(row) {
  return [
    cleanText(row.job_hash),
    cleanText(row.company).toLowerCase(),
    cleanText(row.title).toLowerCase()
  ].join("|");
}

function dedupeJobs(rows) {
  const map = new Map();

  ensureArray(rows).forEach(row => {
    const key = jobKey(row);
    if (!key || key.replace(/\|/g, "").trim() === "") return;
    if (!map.has(key)) map.set(key, row);
  });

  return Array.from(map.values());
}

