  if (r?.choices?.[0]?.message?.content) return r.choices[0].message.content;
  if (r?.body?.choices?.[0]?.message?.content) return r.body.choices[0].message.content;
  if (typeof r === "string") return r;
  return JSON.stringify(r || {});
}

// FIX: Replaced literal backticks with \x60 to prevent n8n from crashing
function stripMarkdownFences(text) {
  return String(text || "")
    .replace(/^\x60{3}json\s*/i, "")
    .replace(/^\x60{3}\s*/i, "")
    .replace(/\s*\x60{3}$/i, "")
    .trim();
}

function extractJsonObject(text) {
  const cleaned = stripMarkdownFences(text);
  try {
    return JSON.parse(cleaned);
  } catch (_) {}

  const firstBrace = cleaned.indexOf("{");
  const lastBrace = cleaned.lastIndexOf("}");
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    const candidate = cleaned.slice(firstBrace, lastBrace + 1);
    return JSON.parse(candidate);
  }

  throw new Error("No valid JSON object found in model response");
}

function safeCoverLetter(text, factText) {
  const lower = String(text || "").toLowerCase();
  const risky = [
    "shrm", "sphr", "phr", "workday certified", "green card", 
    "citizen", "managed a team", "saved $", "increased by", "reduced by"
  ];
  return risky.filter(r => lower.includes(r) && !factText.includes(r));
}

