function buildGoogleSearchUrl(query, apiKey) {
  const params = {
    engine: "google",
    q: query,
    demo_key: apiKey,
    num: "10"
  };

  const queryString = Object.keys(params)
    .map(key => `${encodeURIComponent(key)}=${encodeURIComponent(params[key])}`)
    .join("&");

  return `https://example.com/demo-people-search-disabled?${queryString}`;
}

function buildKeywordSet(job) {
  const title = cleanText(job.title).toLowerCase();
  const desc = cleanText(job.description || job.source_job?.description).toLowerCase();
  const combined = `${title} ${desc}`;

  const base = [
    "Talent Acquisition",
    "Recruiter",
    "Human Resources",
    "HR Operations",
    "HR Business Partner"
  ];

  const fallback = [
    "People Operations",
    "HR Coordinator",
    "HR Specialist"
  ];

  const roleSpecific = [];

  if (/payroll/.test(combined)) {
    roleSpecific.push("Payroll Analyst", "Payroll Specialist");
  }

  if (/benefits|total rewards|compensation/.test(combined)) {
    roleSpecific.push("Benefits Analyst", "Compensation Analyst", "Total Rewards");
  }

  if (/hris|hcm|ats|lms|systems/.test(combined)) {
    roleSpecific.push("HRIS", "HR Systems", "People Systems");
  }

  if (/analytics|people analytics|workforce|reporting|dashboard|data/.test(combined)) {
    roleSpecific.push("People Analytics", "Workforce Analyst", "HR Reporting");
  }

  if (/employee engagement|employee experience/.test(combined)) {
    roleSpecific.push("Employee Experience", "Employee Engagement");
  }

  const all = [...base, ...roleSpecific, ...fallback];

  return [...new Set(all)];
}

