    .replace(/\s+/g, " ")
    .trim();
}

function ensureArray(value) {
  return Array.isArray(value) ? value : [];
}

// THE FIX: Detect blind/confidential jobs so we don't scrape garbage contacts
function isInvalidCompany(company) {
  const normalized = cleanText(company).toLowerCase();
  const invalidList = [
    "not specified", "confidential", "undisclosed", "unknown", 
    "n/a", "tbd", "na", "hidden", "private", "staffing agency"
  ];
  return invalidList.includes(normalized) || normalized.length < 2;
}

function normalizeCompany(value) {
  return cleanText(value)
    .replace(/\([^)]*\)/g, "")
    .replace(/\binc\.?\b|\bllc\b|\bltd\.?\b|\bltd\b|\bcorp\.?\b|\bcorporation\b|\bcompany\b|\bco\.?\b/gi, "")
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9 ]/gi, " ")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function companyTokens(company) {
  const normalized = normalizeCompany(company);

  return normalized
    .split(" ")
    .map(t => t.trim())
    .filter(t =>
      t.length >= 3 &&
      !["the", "and", "for", "with", "group", "services", "solutions"].includes(t)
    );
}

function companyIsMentioned(company, title, snippet, link) {
  // Fail fast if the company name is fake/confidential
  if (isInvalidCompany(company)) return false; 

  const combined = normalizeCompany(`${title} ${snippet} ${link}`);
  const normalizedCompany = normalizeCompany(company);

  if (!normalizedCompany) return false;
  if (combined.includes(normalizedCompany)) return true;

  const tokens = companyTokens(company);
  if (tokens.length === 0) return false;

  return tokens.some(token => combined.includes(token));
}

function extractNameFromTitle(title) {
  let t = cleanText(title);

  t = t.replace(/\s*\|\s*LinkedIn.*$/i, "");
  t = t.replace(/\s*-\s*LinkedIn.*$/i, "");
  t = t.replace(/\s*\|\s*.*$/i, "");

  if (t.includes(" - ")) return cleanText(t.split(" - ")[0]);
  if (t.includes(",")) return cleanText(t.split(",")[0]);

  return t;
}

function extractTitleFromSnippet(title, snippet) {
  const combined = `${cleanText(title)} ${cleanText(snippet)}`;

  const patterns = [
    /Talent Acquisition[^,.|]*/i,
    /Talent Consultant[^,.|]*/i,
    /Talent Partner[^,.|]*/i,
    /Talent Advisor[^,.|]*/i,
    /University Recruiter[^,.|]*/i,
    /Campus Recruiter[^,.|]*/i,
    /Early Careers[^,.|]*/i,
    /Recruiter[^,.|]*/i,
    /Recruiting[^,.|]*/i,
    /Human Resources[^,.|]*/i,
    /HR Business Partner[^,.|]*/i,
    /People Partner[^,.|]*/i,
    /People Operations[^,.|]*/i,
    /HR Operations[^,.|]*/i,
    /HR Coordinator[^,.|]*/i,
    /HR Specialist[^,.|]*/i,
    /Human Resources Coordinator[^,.|]*/i,
    /Human Resources Specialist[^,.|]*/i,
    /Payroll Analyst[^,.|]*/i,
    /Payroll Specialist[^,.|]*/i,
    /Benefits Analyst[^,.|]*/i,
    /Benefits Specialist[^,.|]*/i,
    /Compensation Analyst[^,.|]*/i,
    /Compensation Specialist[^,.|]*/i,
    /Total Rewards[^,.|]*/i,
    /HRIS[^,.|]*/i,
    /HR Systems[^,.|]*/i,
    /People Systems[^,.|]*/i,
    /People Analytics[^,.|]*/i,
    /Workforce Analyst[^,.|]*/i,
    /HR Reporting[^,.|]*/i,
    /Employee Experience[^,.|]*/i,
    /Employee Engagement[^,.|]*/i,
    /Learning and Development[^,.|]*/i,
    /Organizational Development[^,.|]*/i
  ];

  for (const p of patterns) {
    const m = combined.match(p);
    if (m) return cleanText(m[0]);
  }

  if (title.includes(" - ")) {
    const parts = title.split(" - ").map(cleanText).filter(Boolean);
    if (parts.length >= 2) return parts[1];
  }

  return "Company employee";
}

function hasHrPeopleRelevance(title, snippet, keyword) {
  const text = `${title} ${snippet} ${keyword}`.toLowerCase();

  const hrSignals = [
    "talent acquisition", "talent consultant", "talent partner", "talent advisor",
    "recruiter", "recruiting", "university recruiter", "campus recruiter", "early careers",
    "human resources", "hr business partner", "people partner", "people operations",
    "hr operations", "hr coordinator", "hr specialist", "payroll analyst",
    "payroll specialist", "benefits analyst", "benefits specialist",
    "compensation analyst", "compensation specialist", "total rewards",
    "hris", "hr systems", "people systems", "people analytics", "workforce analyst",
    "hr reporting", "employee experience", "employee engagement",
    "learning and development", "organizational development"
  ];

  return hrSignals.some(signal => text.includes(signal));
}

function isBadNonHrMatch(title, snippet) {
  const text = `${title} ${snippet}`.toLowerCase();

  if (hasHrPeopleRelevance(title, snippet, "")) return false;

  const badSignals = [
    "strategic sourcing", "procurement", "supply chain", "category management",
    "sales", "account executive", "business development", "marketing", "finance",
    "accounting", "software engineer", "data engineer", "product manager",
    "project management", "operations manager", "warehouse", "logistics",
    "customer success", "consultant", "student", "intern"
  ];

  return badSignals.some(signal => text.includes(signal));
}

function scoreContact(contactTitle, title, snippet) {
  const text = `${contactTitle} ${title} ${snippet}`.toLowerCase();
  let score = 55;

  if (/talent acquisition|talent consultant|talent partner|talent advisor|recruiter|recruiting|university recruiter|campus recruiter|early careers/.test(text)) score += 40;
  else if (/hr business partner|people partner|hr operations|people operations/.test(text)) score += 34;
  else if (/human resources|hr coordinator|hr specialist/.test(text)) score += 30;
  else if (/payroll|benefits|compensation|total rewards|hris|people systems|people analytics|workforce|hr reporting/.test(text)) score += 22;
  else if (/employee experience|employee engagement|learning and development|organizational development/.test(text)) score += 18;

  if (/manager|lead|partner|director|head|senior/.test(text)) score += 5;
  if (/student|assistant intern/.test(text)) score -= 10;

  return Math.max(0, Math.min(100, score));
}

function priorityFromScore(score) {
  if (score >= 90) return "1 - highest";
  if (score >= 82) return "2 - high";
  if (score >= 74) return "3 - medium-high";
  if (score >= 65) return "4 - medium";
  return "5 - low";
}

function buildWhy(contactTitle, company) {
  const t = `${contactTitle}`.toLowerCase();

  if (/talent acquisition|talent consultant|talent partner|talent advisor|recruiter|recruiting|university recruiter|campus recruiter|early careers/.test(t)) {
    return `Likely connected to recruiting or candidate routing at ${company}.`;
  }
  if (/hr business partner|people partner|hr operations|people operations/.test(t)) {
    return `Strong HR functional match and likely familiar with HR team needs at ${company}.`;
  }
  if (/hr coordinator|hr specialist|human resources/.test(t)) {
    return `Close to HR operations work and may provide practical role guidance at ${company}.`;
  }
  if (/payroll|benefits|compensation|total rewards|hris|people systems|people analytics|workforce|hr reporting/.test(t)) {
    return `Role-adjacent HR contact who may understand department structure and referral direction at ${company}.`;
  }
  if (/employee experience|employee engagement|learning and development|organizational development/.test(t)) {
    return `People-team adjacent contact who may help with role guidance or referral direction at ${company}.`;
  }
  return `Company contact with possible HR relevance at ${company}.`;
}

