const found = [];
const rejected = [];
let isBlindJob = false;

inputItems.forEach((item, index) => {
  const data = item.json || {};
  const req = getPreparedRequestByIndex(index, data);
  const organic = ensureArray(data.organic_results);

  const targetCompany = cleanText(req.company || baseItem.company || "Not specified");
  const targetKeyword = cleanText(req.keyword);
  const targetJobHash = cleanText(req.job_hash);
  const targetRunId = cleanText(req.run_id || baseItem.run_id);

  // Stop processing if this is a blind or confidential job
  if (isInvalidCompany(targetCompany)) {
    isBlindJob = true;
    rejected.push({
      reason: "blind_job_or_invalid_company",
      target_company: targetCompany,
      search_keyword: targetKeyword
    });
    return;
  }

  organic.forEach(result => {
    const link = cleanText(result.link);
    const title = cleanText(result.title);
    const snippet = cleanText(result.snippet);

    if (!link || !/linkedin\.com\/in\//i.test(link)) return;
    if (!title) return;

    const companyMatch = companyIsMentioned(targetCompany, title, snippet, link);

    if (!companyMatch) {
      rejected.push({ reason: "company_not_confirmed", target_company: targetCompany, result_title: title, result_link: link });
      return;
    }

    const hrRelevant = hasHrPeopleRelevance(title, snippet, targetKeyword);
    if (!hrRelevant) {
      rejected.push({ reason: "not_hr_people_relevant", target_company: targetCompany, result_title: title, result_link: link });
      return;
    }

    if (isBadNonHrMatch(title, snippet)) {
      rejected.push({ reason: "bad_non_hr_match", target_company: targetCompany, result_title: title, result_link: link });
      return;
    }

    const contactName = extractNameFromTitle(title);
    if (!contactName || contactName.length < 3) {
      rejected.push({ reason: "bad_contact_name", target_company: targetCompany, result_title: title, result_link: link });
      return;
    }

    if (/linkedin|profiles|people|jobs|directory|company/i.test(contactName)) {
      rejected.push({ reason: "generic_linkedin_result", target_company: targetCompany, result_title: title, result_link: link });
      return;
    }

    const contactTitle = extractTitleFromSnippet(title, snippet);
    const relevanceScore = scoreContact(contactTitle, title, snippet);

    if (relevanceScore < 74) {
      rejected.push({ reason: "low_relevance_score", target_company: targetCompany, result_title: title, result_link: link, score: relevanceScore });
      return;
    }

    found.push({
      run_id: targetRunId,
      job_hash: targetJobHash,
      company: targetCompany,
      contact_name: contactName,
      contact_title: contactTitle,
      linkedin_url: link,
      source_url: link,
      relevance_score: relevanceScore,
      contact_priority: priorityFromScore(relevanceScore),
      why_this_contact: buildWhy(contactTitle, targetCompany),
      suggested_action: "Review profile manually, then send a short LinkedIn message asking for guidance or referral direction.",
      _dedupe_key: `${targetCompany}|${contactName}|${link}`.toLowerCase()
    });
  });
});

const dedupedMap = new Map();

found.forEach(contact => {
  const existing = dedupedMap.get(contact._dedupe_key);
  if (!existing || Number(contact.relevance_score || 0) > Number(existing.relevance_score || 0)) {
    dedupedMap.set(contact._dedupe_key, contact);
  }
});

const maxContacts = Number(baseItem.config?.max_contacts_per_company || baseItem.config?.max_contacts_per_job || 2);

