const inputItems = $input.all();
const now = new Date().toISOString();

function cleanText(value) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .trim();
}

function ensureArray(value) {
  return Array.isArray(value) ? value : [];
}

function toNumber(value, fallback) {
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? n : fallback;
}

function firstNumber(values, fallback) {
  for (const value of values) {
    const n = Number(value);
    if (Number.isFinite(n) && n > 0) return n;
  }
  return fallback;
}

function isManualPlaceholderContact(row) {
  const name = cleanText(row.contact_name);
  const linkedin = cleanText(row.linkedin_url);
  const source = cleanText(row.source_url);

  return (
    name.startsWith("Manual Search Target") ||
    linkedin.includes('"') ||
    source.includes('"') ||
    linkedin.toLowerCase().includes("linkedin search") ||
    source.toLowerCase().includes("linkedin search")
  );
}

function hasRealLinkedInContact(row) {
  const url = cleanText(row.linkedin_url || row.source_url);
  const name = cleanText(row.contact_name);

  return (
    name &&
    !name.startsWith("Manual Search Target") &&
    /^https?:\/\/(www\.)?linkedin\.com\/in\//i.test(url)
  );
}

function contactDedupeKey(row) {
  return [
    cleanText(row.job_hash),
    cleanText(row.company).toLowerCase(),
    cleanText(row.contact_name).toLowerCase(),
    cleanText(row.linkedin_url || row.source_url).toLowerCase()
  ].join("|");
}

function outreachDedupeKey(row) {
  return [
    cleanText(row.job_hash),
    cleanText(row.company).toLowerCase(),
    cleanText(row.contact_name).toLowerCase(),
    cleanText(row.message_draft).slice(0, 80).toLowerCase()
  ].join("|");
}

function dedupeRows(rows, keyFn) {
  const map = new Map();

  rows.forEach(row => {
    const key = keyFn(row);
    if (!key || key.replace(/\|/g, "").trim() === "") return;

    const existing = map.get(key);

    if (!existing) {
      map.set(key, row);
      return;
    }

    const currentScore = Number(row.relevance_score || 0);
    const existingScore = Number(existing.relevance_score || 0);

    if (currentScore > existingScore) {
      map.set(key, row);
    }
  });

  return Array.from(map.values());
}

function sortContacts(rows) {
  return rows.sort((a, b) => {
    const aScore = Number(a.relevance_score || 0);
    const bScore = Number(b.relevance_score || 0);
    return bScore - aScore;
  });
}

function capContacts(rows, maxContacts) {
  const all = ensureArray(rows);

  const real = all.filter(hasRealLinkedInContact);
  const manualNonPlaceholder = all.filter(row => !hasRealLinkedInContact(row) && !isManualPlaceholderContact(row));
  const placeholders = all.filter(isManualPlaceholderContact);

  if (real.length > 0) {
    return sortContacts(dedupeRows(real, contactDedupeKey)).slice(0, maxContacts);
  }

  if (manualNonPlaceholder.length > 0) {
    return sortContacts(dedupeRows(manualNonPlaceholder, contactDedupeKey)).slice(0, maxContacts);
  }

  return sortContacts(dedupeRows(placeholders, contactDedupeKey)).slice(0, maxContacts);
}

function capOutreach(rows, allowedContacts, maxOutreach) {
  const allowedKeys = new Set(
    allowedContacts.map(c =>
      [
        cleanText(c.job_hash),
        cleanText(c.company).toLowerCase(),
        cleanText(c.contact_name).toLowerCase()
      ].join("|")
    )
  );

  const filtered = ensureArray(rows).filter(row => {
    const key = [
      cleanText(row.job_hash),
      cleanText(row.company).toLowerCase(),
      cleanText(row.contact_name).toLowerCase()
    ].join("|");

    return allowedKeys.has(key);
  });

  return dedupeRows(filtered, outreachDedupeKey).slice(0, maxOutreach);
}

function capGenericByJob(rows, maxRows) {
  const all = ensureArray(rows);
  const map = new Map();

  all.forEach(row => {
    const key = [
      cleanText(row.job_hash),
      cleanText(row.company).toLowerCase(),
      cleanText(row.title).toLowerCase()
    ].join("|");

    if (!map.has(key)) {
      map.set(key, row);
    }
  });

  return Array.from(map.values()).slice(0, maxRows);
}

// Prefer the last item because it usually has Final Writer Payload.
let item = inputItems[inputItems.length - 1]?.json || {};

item.logs = Array.isArray(item.logs) ? item.logs : [];
item.config = item.config || {};
item.sheet_rows = item.sheet_rows || {};

// Dynamic limits from control dashboard/config.
