    item.config.max_contacts_per_company,
    item.config.max_contacts_per_job,
    item.config.target_contacts_per_company
  ],
  5
);

const maxOutreach = firstNumber(
  [
    item.config.max_outreach_per_run,
    item.config.max_contacts_per_company,
    item.config.max_contacts_per_job,
    item.config.target_contacts_per_company
  ],
  maxContacts
);

const maxResumes = firstNumber(
  [
    item.config.max_resumes_per_run,
    item.config.max_google_docs_per_run
  ],
  1
);

const maxDocs = firstNumber(
  [
    item.config.max_google_docs_per_run,
