);

// Merge possible duplicate arrays from incoming items.
const mergedContacts = [];
const mergedOutreach = [];
const mergedTailoredResumes = [];
const mergedDocRequests = [];

inputItems.forEach(i => {
  const json = i.json || {};

  mergedContacts.push(...ensureArray(json.contacts));
  mergedContacts.push(...ensureArray(json.sheet_rows?.Contacts));

  mergedOutreach.push(...ensureArray(json.outreach));
  mergedOutreach.push(...ensureArray(json.sheet_rows?.Outreach));

  mergedTailoredResumes.push(...ensureArray(json.tailored_resumes));
  mergedTailoredResumes.push(...ensureArray(json.sheet_rows?.Tailored_Resumes));

  mergedDocRequests.push(...ensureArray(json.doc_generation_requests));
});

// Apply caps
const cappedContacts = capContacts(
  mergedContacts.length ? mergedContacts : item.sheet_rows.Contacts,
  maxContacts
);

const cappedOutreach = capOutreach(
  mergedOutreach.length ? mergedOutreach : item.sheet_rows.Outreach,
