const ALL_HEADINGS = Object.values(FIELD_ALIASES).flat();

function normalizeHeadings(raw) {
  let text = cleanText(raw);

  ALL_HEADINGS
    .sort((a, b) => b.length - a.length)
    .forEach(h => {
      const escaped = escapeRegex(h);
      const re = new RegExp(`\\s+(${escaped}\\s*:)`, "gi");
      text = text.replace(re, "\n$1");
    });

  text = text
    .replace(/\s+•\s*/g, "\n• ")
    .replace(/\s+-\s+/g, "\n- ")
    .replace(/\n{3,}/g, "\n\n")
    .trim();

  return text;
}

function extractByAliases(text, aliases) {
  const normalized = normalizeHeadings(text);

  const allHeadingsPattern = ALL_HEADINGS
    .sort((a, b) => b.length - a.length)
    .map(escapeRegex)
    .join("|");

  for (const alias of aliases) {
    const escaped = escapeRegex(alias);

    const regex = new RegExp(
      `(?:^|\\n)\\s*${escaped}\\s*:\\s*([\\s\\S]*?)(?=\\n\\s*(?:${allHeadingsPattern})\\s*:|$)`,
      "i"
    );

    const match = normalized.match(regex);
    if (match && cleanText(match[1])) {
      return cleanText(match[1]);
    }
  }

  return "";
}

function extractBullets(value) {
  const text = cleanText(value);
  if (!text) return [];

  return text
    .split(/\n+/)
    .flatMap(line => line.split(/\s*•\s*/))
    .map(line => line.replace(/^[•\-\*\u2022]\s*/, "").trim())
    .filter(Boolean);
}

function inferKnownCompany(raw) {
