  ];

  for (const company of knownCompanies) {
    if (text.includes(company.toLowerCase())) return company;
  }

  return "";
}

function inferTitle(raw) {
  const text = cleanInline(raw);

  const override = firstNonEmpty(
    item.manual_job_title_override,
    item.handshake_job_title_override,
    item.job_title_override,
    item.title_override
  );
  if (override) return override;

  const labeled = extractByAliases(raw, FIELD_ALIASES.title);
  if (labeled) return cleanInline(labeled).split("\n")[0];

  const titlePatterns = [
    /\b(HR Representative)\b/i,
    /\b(Human Resources Representative)\b/i,
    /\b(HR Assistant Intern)\b/i,
    /\b(Human Resources Intern)\b/i,
    /\b(HR Intern)\b/i,
    /\b(People Operations Intern)\b/i,
    /\b(People Analytics Intern)\b/i,
    /\b(Talent Acquisition Intern)\b/i,
    /\b(HR Operations Intern)\b/i,
    /\b(HR Coordinator)\b/i,
    /\b(HR Generalist)\b/i,
    /\b(Payroll Analyst)\b/i,
    /\b(Benefits Analyst)\b/i,
    /\b(Recruiting Coordinator)\b/i,
    /\b(Total Rewards Intern)\b/i,
    /\b(Compensation Intern)\b/i
  ];

  for (const pattern of titlePatterns) {
    const match = text.match(pattern);
    if (match) return cleanInline(match[1]);
  }

  if (/human resources|hr\b|people operations|talent acquisition/i.test(text)) {
    return "Human Resources Role - Manual Review Required";
  }

  return "Manual Job Posting - Review Required";
}

function inferCompany(raw) {
  const text = cleanInline(raw);

  const override = firstNonEmpty(
    item.manual_company_override,
    item.handshake_company_override,
    item.company_override
  );
  if (override) return override;

  const labeled = extractByAliases(raw, FIELD_ALIASES.company);
  if (labeled) return cleanInline(labeled).split("\n")[0];

  const known = inferKnownCompany(raw);
  if (known) return known;

  const logoMatch = text.match(/^(.{2,80}?)\s+logo\s+/i);
  if (logoMatch) return cleanInline(logoMatch[1]);

  const beforeIndustryMatch = text.match(/^(.{2,90}?)\s+(Transportation\s*&\s*Logistics|Human Resources|Retail|Technology|Healthcare|Finance|Manufacturing|Supply Chain)\s+/i);
  if (beforeIndustryMatch) return cleanInline(beforeIndustryMatch[1]).replace(/\s+logo$/i, "");

  return "Company Not Parsed - Manual Review Required";
}

function cleanLocationText(value) {
  return cleanInline(value)
    .replace(/,\s+or\s+/i, " or ")
    .replace(/\s+or\s+/i, " or ")
    .replace(/\s+/g, " ")
    .trim();
}

function inferLocation(raw) {
  const text = cleanInline(raw);

  const override = firstNonEmpty(
    item.manual_location_override,
    item.handshake_location_override,
    item.location_override
  );
  if (override) return cleanLocationText(override);

  const labeled = extractByAliases(raw, FIELD_ALIASES.location);
  if (labeled) return cleanLocationText(cleanInline(labeled).split("\n")[0]);

  const basedIn = text.match(/based in\s+([^\.]+?)(?:\s+Work in person|\s+Work from|\s+Job\b|\s+Full[- ]time|\s+Part[- ]time|\s+Remote|\s+Hybrid|$)/i);
  if (basedIn) return cleanLocationText(basedIn[1]);

  const cityStateMatches = text.match(/\b[A-Z][a-zA-Z .'-]+,\s*[A-Z]{2}\b/g);
  if (cityStateMatches && cityStateMatches.length) {
    const unique = [...new Set(cityStateMatches.map(cleanInline))];

    if (unique.some(x => /Groveport,\s*OH/i.test(x)) && unique.some(x => /Columbus,\s*OH/i.test(x))) {
      return "Groveport, OH or Columbus, OH";
    }

    return cleanLocationText(unique.slice(0, 2).join(" or "));
  }

  return "Location Not Parsed - Manual Review Required";
}

function inferWorkMode(raw) {
  const labeled = extractByAliases(raw, FIELD_ALIASES.work_mode);
  if (labeled) return cleanInline(labeled).split("\n")[0];

  const text = lower(raw);

  if (text.includes("work in person") || text.includes("onsite") || text.includes("on-site")) return "Onsite";
  if (text.includes("hybrid")) return "Hybrid";
  if (text.includes("remote")) return "Remote";

  return "Not specified";
}

function inferEmploymentType(raw, title) {
  const labeled = extractByAliases(raw, FIELD_ALIASES.employment_type);
  if (labeled) return cleanInline(labeled).split("\n")[0];

  const text = lower(`${raw} ${title}`);

  if (text.includes("full-time internship") || text.includes("full time internship")) return "Full-Time Internship";
  if (text.includes("part-time internship") || text.includes("part time internship")) return "Part-Time Internship";
  if (text.includes("internship") || /\bintern\b/.test(text)) return "Internship";
  if (text.includes("full-time") || text.includes("full time")) return "Full-Time";
  if (text.includes("part-time") || text.includes("part time")) return "Part-Time";
  if (text.includes("contract")) return "Contract";

  return "Not specified";
}

function normalizeSalaryText(value) {
  let text = cleanInline(value);

  if (!text) return "Not listed";

  text = text
    .replace(/^national salary range of\s+/i, "")
    .replace(/\s+/g, " ")
    .trim();

  const compact = text.match(/\$(\d{2,3})\s*[-–]\s*(\d{2,3})K\s*\/?\s*yr/i);
  if (compact) {
    return `$${compact[1]},000 - $${compact[2]},000 per year`;
  }

  const compactBoth = text.match(/\$(\d{2,3})K\s*[-–]\s*\$?(\d{2,3})K\s*\/?\s*yr/i);
  if (compactBoth) {
    return `$${compactBoth[1]},000 - $${compactBoth[2]},000 per year`;
  }

  const annual = text.match(/\$(\d{2,3},\d{3})\s*[-–]\s*\$?(\d{2,3},\d{3})/i);
  if (annual) {
    return `$${annual[1]} - $${annual[2]} per year`;
  }

  const hourly = text.match(/\$(\d{1,3}(?:\.\d{1,2})?)\s*\/?\s*(?:hr|hour|per hour)/i);
  if (hourly) {
    return `$${hourly[1]} per hour`;
  }

  return text;
}

function inferSalary(raw) {
  const labeled = extractByAliases(raw, FIELD_ALIASES.salary);
  if (labeled) {
    const cleanLabeled = cleanInline(labeled).split("\n")[0];
    const normalizedLabeled = normalizeSalaryText(cleanLabeled);
    if (normalizedLabeled !== "Not listed") return normalizedLabeled;
  }

  const text = cleanInline(raw);

  const fullAnnualRange =
    text.match(/\$\d{2,3},\d{3}\s*[-–]\s*\$?\d{2,3},\d{3}(?:\s*per year|\s*\/yr)?/i) ||
    text.match(/national salary range of\s+\$\d{2,3},\d{3}\s*[-–]\s*\$?\d{2,3},\d{3}/i);

  if (fullAnnualRange) {
    return normalizeSalaryText(fullAnnualRange[0]);
  }

  const compactKRange =
    text.match(/\$\d{2,3}\s*[-–]\s*\d{2,3}K\s*\/?\s*yr/i) ||
    text.match(/\$\d{2,3}K\s*[-–]\s*\$?\d{2,3}K\s*\/?\s*yr/i);

  if (compactKRange) {
    return normalizeSalaryText(compactKRange[0]);
  }

  const hourly =
    text.match(/\$\d{1,3}(?:\.\d{1,2})?\s*\/\s*(?:hour|hr)/i) ||
    text.match(/\$\d{1,3}(?:\.\d{1,2})?\s*(?:per hour|\/hour|\/hr)/i);

  if (hourly) {
    return normalizeSalaryText(hourly[0]);
  }

  const looseRange =
    text.match(/\$\d{2,3},?\d{0,3}\s*[-–]\s*\$?\d{2,3},?\d{0,3}/i);

  if (looseRange) {
    return normalizeSalaryText(looseRange[0]);
  }

  return "Not listed";
}

function inferPostedDate(raw) {
  const labeled = extractByAliases(raw, FIELD_ALIASES.posted_date);
  if (labeled) return cleanInline(labeled).split("\n")[0];

  const posted = cleanInline(raw).match(/Posted\s+\d+\s+(?:day|days|week|weeks|month|months)\s+ago/i);
  if (posted) return posted[0];

  return "manual_input";
}

function inferDeadline(raw) {
  const override = firstNonEmpty(
    item.manual_deadline_override,
    item.handshake_deadline_override
  );
  if (override) return override;

  const labeled = extractByAliases(raw, FIELD_ALIASES.deadline);
  if (labeled) return cleanInline(labeled).split("\n")[0];

  const deadline = cleanInline(raw).match(/Apply by\s+([A-Z][a-z]+\s+\d{1,2},\s+\d{4}(?:\s+at\s+\d{1,2}:\d{2}\s+[AP]M)?)/i);
  if (deadline) return cleanInline(deadline[1]);

  return "Not listed";
}

function inferHours(raw) {
  const labeled = extractByAliases(raw, FIELD_ALIASES.hours);
  if (labeled) return cleanText(labeled);

  const text = cleanInline(raw);
  const pieces = [];

  if (/full[- ]time/i.test(text)) pieces.push("Full-time");

  if (/2nd Shift/i.test(text) || /3p-11p/i.test(text)) {
    pieces.push("2nd Shift: Monday-Friday, 3:00 PM-11:00 PM");
  }

  if (/3rd Shift/i.test(text) || /10p-6a/i.test(text)) {
    pieces.push("Flex to 3rd Shift during peak periods: Sunday-Thursday, 10:00 PM-6:00 AM");
  }

  return pieces.length ? pieces.join("\n") : "Not specified";
}

function inferIndustry(raw) {
  const labeled = extractByAliases(raw, FIELD_ALIASES.industry);
  if (labeled) return cleanInline(labeled).split("\n")[0];

  const text = lower(raw);

  if (/logistics|supply chain|transportation|distribution center|warehouse/.test(text)) return "Transportation & Logistics";
  if (/healthcare|hospital|patient/.test(text)) return "Healthcare";
  if (/finance|bank|investment/.test(text)) return "Financial Services";
  if (/technology|software|saas/.test(text)) return "Technology";
  if (/retail|store|customer/.test(text)) return "Retail";
  if (/manufacturing|production|plant/.test(text)) return "Manufacturing";

  return "Not specified";
}

function inferWorkAuth(raw) {
  const labeled = extractByAliases(raw, FIELD_ALIASES.work_auth);
  if (labeled) return cleanInline(labeled).split("\n")[0];

  const text = cleanInline(raw);

  if (/US work authorization required/i.test(text)) return "US work authorization required.";
  if (/sponsorship.*not.*available|no sponsorship/i.test(text)) return "Sponsorship not mentioned or not available.";
  if (/work authorization|work authorization/i.test(text)) return "work authorization mentioned. Review posting manually.";

  return "Not specified";
}

function inferCptNotes(raw, workAuth) {
  const labeled = extractByAliases(raw, FIELD_ALIASES.cpt_opt);
  if (labeled) return cleanInline(labeled).split("\n")[0];

  const text = cleanInline(raw);

  if (/work authorization accepted|work authorization accepted/i.test(text)) return "work authorization appears mentioned as accepted. School approval still required.";
  if (/US work authorization required/i.test(text)) return "No work authorization, work authorization, or work authorization sponsorship information mentioned. Posting states US work authorization required.";
  if (/sponsorship.*not.*available|no sponsorship/i.test(text)) return "Work authorization sponsorship appears unavailable or not mentioned.";
  if (workAuth && workAuth !== "Not specified") return "Work authorization mentioned. work authorization must be reviewed manually.";

  return "Not specified";
}

function inferResponsibilities(raw) {
  const labeled = extractByAliases(raw, FIELD_ALIASES.responsibilities);
  let bullets = extractBullets(labeled);

  if (bullets.length) return bullets;

  const text = lower(raw);
  const tasks = [];

  const taskMap = [
    ["implement hr strategies", "Implement HR strategies and initiatives aligned with business objectives"],
    ["employee relations", "Support employee relations and engagement initiatives"],
    ["engagement", "Support employee engagement and workplace culture activities"],
    ["advocate", "Serve as an advocate and advisor to employees"],
    ["internal investigations", "Conduct or support internal investigations as needed"],
    ["compliance", "Ensure compliance with HR regulations, policies, and laws"],
    ["audit", "Support HR audits and compliance activities"],
    ["train management", "Train or support managers on interviewing, hiring, performance management, safety, and harassment prevention"],
    ["coach", "Coach and advise managers on employee matters"],
    ["staffing", "Assist with staffing and workforce planning processes"],
    ["succession", "Support succession planning and associate programs"],
    ["compensation", "Support compensation and benefits communication"],
    ["benefits", "Support benefits administration and employee communication"],
    ["performance management", "Support performance management processes"],
    ["hrms", "Enter and maintain HR data in HRMS systems"],
    ["hris", "Enter and maintain HR data in HRIS systems"],
    ["post job", "Post job vacancies and support recruiting coordination"],
    ["arrange interviews", "Arrange interviews and support candidate scheduling"],
    ["candidate assessments", "Support initial candidate assessments"],
    ["employee records", "Maintain employee records and HR documentation"],
    ["schedule meetings", "Schedule meetings and provide HR administrative support"],
    ["correspondence", "Handle HR correspondence and professional communication"]
  ];

  taskMap.forEach(([signal, task]) => {
    if (text.includes(signal)) tasks.push(task);
  });

  return tasks.length
    ? [...new Set(tasks)]
    : [
        "Support job responsibilities listed in the posting.",
        "Maintain accurate records and documentation related to the role.",
        "Communicate with stakeholders and support assigned operational tasks."
      ];
}

function inferQualifications(raw) {
  const labeled = extractByAliases(raw, FIELD_ALIASES.qualifications);
  let bullets = extractBullets(labeled);

  if (bullets.length) return bullets;

  const text = lower(raw);
  const quals = [];

  if (text.includes("bachelor")) quals.push("Bachelor's degree required or equivalent experience.");
  if (text.includes("master")) quals.push("Master's degree or graduate coursework may be relevant.");
  if (/hr systems|hrms|hris|database/.test(text)) quals.push("Knowledge of HR systems, HRMS/HRIS, or databases preferred.");
  if (/labor law|hr best practices/.test(text)) quals.push("Knowledge of labor laws and HR best practices preferred.");
  if (/conflict resolution/.test(text)) quals.push("Conflict resolution experience preferred.");
  if (/investigation/.test(text)) quals.push("Experience supporting or conducting investigations preferred.");
  if (/data analytics/.test(text)) quals.push("Data analytics experience preferred.");
  if (/training|facilitating/.test(text)) quals.push("Training facilitation experience preferred.");
  if (/onboarding/.test(text)) quals.push("Onboarding experience preferred.");
  if (/microsoft office|excel/.test(text)) quals.push("Microsoft Office and Excel skills preferred.");

  return quals.length
    ? [...new Set(quals)]
    : [
        "Relevant education, coursework, or experience required.",
        "Strong communication, organization, and attention to detail preferred.",
        "Ability to work with confidential information professionally."
      ];
}

