function inferEmployerDescription(raw, company, industry) {
  const labeled = extractByAliases(raw, FIELD_ALIASES.employer_description);
  if (labeled) return labeled;

  if (/dhl supply chain/i.test(raw)) {
    return "DHL Supply Chain is a global logistics and supply chain management company providing warehousing, transportation, distribution, and supply chain solutions.";
  }

  if (/on-target supplies/i.test(raw)) {
    return "On-Target Supplies & Logistics is a regional logistics management firm serving global customers through customized transportation and logistics solutions.";
  }

  if (company && company !== "Company Not Parsed - Manual Review Required") {
    return `${company} is an employer in the ${industry || "listed"} industry. Review original posting for full employer details.`;
  }

  return "Employer description not provided in posting.";
}

function inferCptRisk(workAuthNotes, cptNotes) {
  const combined = `${workAuthNotes} ${cptNotes}`.toLowerCase();

  if (combined.includes("cpt accepted") || combined.includes("opt accepted")) {
    return {
      cpt_risk: "lower_review",
      cpt_review_required: true,
      notes: "work authorization appears accepted or mentioned, but school approval is still required."
    };
  }

  if (
    combined.includes("no cpt") ||
    combined.includes("no opt") ||
    combined.includes("no sponsorship") ||
    combined.includes("us work authorization required")
  ) {
    return {
      cpt_risk: "review_required",
      cpt_review_required: true,
      notes: "Work authorization language requires manual work authorization review before applying."
    };
  }

  return {
    cpt_risk: "unknown_review",
    cpt_review_required: true,
    notes: "Work authorization details are unclear. Review before applying."
  };
}

