    recruiting_talent: 0,
    payroll_hr_operations: 0,
    hris_hr_operations: 0,
    hr_analytics: 0,
    hr_operations: 0
  };

  scores.employee_relations_hr_operations += countSignals(text, [
    "employee relations",
    "employee engagement",
    "engagement",
    "site climate",
    "site culture",
    "workplace culture",
    "internal investigations",
    "investigations",
    "conflict resolution",
    "performance management",
    "performance review",
    "manager coaching",
    "coach managers",
    "counsel to hourly",
    "counsel to exempt",
    "advocate and counsel",
    "hr compliance",
    "compliance",
    "labor law",
    "hr best practices",
    "policies and laws",
    "audit activities",
    "sexual harassment",
    "terminations",
    "promotions"
  ]);

  scores.benefits_total_rewards += countSignals(text, [
    "benefits",
    "benefits communication",
    "compensation",
    "total rewards",
    "medical",
    "dental",
    "vision",
    "pto",
    "paid time off",
    "fsa",
    "hsa",
    "life insurance",
    "disability insurance"
  ]);

  scores.recruiting_talent += countSignals(text, [
    "recruiting",
    "talent acquisition",
    "candidate",
    "interview",
    "interviewing",
    "interview scheduling",
    "hiring",
    "pre-employment",
    "applicant",
    "staffing"
  ]);

  scores.payroll_hr_operations += countSignals(text, [
    "payroll",
    "payroll data",
    "timekeeping",
    "wage",
    "salary",
    "compensation data"
  ]);

  scores.hris_hr_operations += countSignals(text, [
    "hris",
    "hrms",
    "hr systems",
    "hr databases",
    "databases",
    "enter and maintain data",
    "employee data",
    "employee records",
    "hr data"
  ]);

  scores.hr_analytics += countSignals(text, [
    "people analytics",
    "hr analytics",
    "data analytics",
    "dashboard",
    "reporting",
    "power bi",
    "tableau",
    "workforce data",
    "people data"
  ]);

  scores.hr_operations += countSignals(text, [
    "human resources",
    "hr representative",
    "hr operations",
    "employee records",
    "hr documentation",
    "onboarding",
    "administrative support",
    "employee lifecycle",
    "hr support",
    "customer service to business leaders"
  ]);

  if (title.includes("hr representative") || title.includes("human resources representative")) {
    scores.employee_relations_hr_operations += 5;
    scores.hr_operations += 4;
  }

  if (title.includes("hr assistant")) {
    scores.hr_operations += 4;
    scores.recruiting_talent += 2;
  }

  if (title.includes("people analytics")) {
    scores.hr_analytics += 5;
  }

  if (title.includes("payroll")) {
    scores.payroll_hr_operations += 5;
  }

  if (title.includes("benefits") || title.includes("compensation") || title.includes("total rewards")) {
    scores.benefits_total_rewards += 5;
  }

  if (title.includes("recruit") || title.includes("talent acquisition")) {
    scores.recruiting_talent += 5;
  }

  const ranked = Object.entries(scores)
    .sort((a, b) => b[1] - a[1]);

  const bestAngle = ranked[0][0];
  const bestScore = ranked[0][1];

  if (bestScore <= 0) return "hr_operations";

  return bestAngle;
}

function shouldOverrideExistingAngle(existingAngle, inferredAngle, job) {
  const existing = cleanText(existingAngle);
  const inferred = cleanText(inferredAngle);
  const text = jobText(job);

  if (!existing) return true;
  if (existing === inferred) return false;

  const strongEmployeeRelationsRole =
    text.includes("employee relations") ||
    text.includes("internal investigations") ||
    text.includes("performance management") ||
    text.includes("manager coaching") ||
    text.includes("compliance with required regulations") ||
    text.includes("hr representative");

  const weakPeopleAnalyticsAngle =
    existing === "people_analytics" &&
    inferred !== "hr_analytics";

  if (strongEmployeeRelationsRole && weakPeopleAnalyticsAngle) return true;

  const strongBenefitsRole =
    text.includes("benefits") &&
    (text.includes("compensation") || text.includes("total rewards") || text.includes("benefits communication"));

  if (strongBenefitsRole && existing === "people_analytics") return true;

  const strongRecruitingRole =
    text.includes("recruiting") ||
    text.includes("talent acquisition") ||
    text.includes("candidate communication") ||
    text.includes("interview scheduling");

  if (strongRecruitingRole && existing === "people_analytics") return true;

  return false;
}

function finalResumeAngle(job) {
  const existingAngle = firstNonEmpty(job.resume_angle, item.resume_angle);
  const inferredAngle = inferResumeAngle(job);

  if (shouldOverrideExistingAngle(existingAngle, inferredAngle, job)) {
    return {
      resume_angle: inferredAngle,
      resume_angle_source: "auto_corrected_from_job_description",
      previous_resume_angle: existingAngle || "",
      inferred_resume_angle: inferredAngle
    };
  }

  return {
    resume_angle: existingAngle || inferredAngle || "hr_operations",
    resume_angle_source: existingAngle ? "kept_existing_angle" : "inferred_from_job_description",
    previous_resume_angle: existingAngle || "",
    inferred_resume_angle: inferredAngle
  };
}

function estimateMatchScore(job) {
  const text = jobText(job);

  let score = 55;

  const strongSignals = [
    "human resources",
    "hr",
    "employee relations",
    "employee engagement",
    "employee records",
    "onboarding",
    "recruiting",
    "candidate",
    "interview",
    "benefits",
    "compensation",
    "payroll",
    "hris",
    "hrms",
    "compliance",
    "performance management",
    "data analytics",
    "excel",
    "reporting"
  ];

  strongSignals.forEach(signal => {
    if (text.includes(signal)) score += 2;
  });

  if (text.includes("bachelor degree required") || text.includes("bachelor's degree required")) {
    score += 2;
  }

  if (text.includes("master")) {
    score += 2;
  }

  if (text.includes("full-time") && text.includes("us work authorization required")) {
    score -= 4;
  }

  if (score > 94) score = 94;
  if (score < 50) score = 50;

  return score;
}

