function calculateScore(job, resumeText) {
  const keywords = extractJobKeywords(job);

  if (!keywords.length) {
    return {
      score: 72,
      coverage: 0,
      matched: [],
      missing: [],
      job_keywords: [],
      notes: "No strong job keywords were extracted."
    };
  }

  const matched = [];
  const missing = [];

  keywords.forEach(k => {
    if (containsPhrase(resumeText, k)) matched.push(k);
    else missing.push(k);
  });

  const coverage = matched.length / keywords.length;

  let score = 50;
  score += Math.round(coverage * 42);

  const criticalSignals = [
    "human resources",
    "hr operations",
    "employee records",
    "hr documentation",
    "onboarding",
    "recruiting",
    "benefits",
    "hr compliance",
    "employee relations",
    "performance management",
    "hris",
    "hrms",
    "data analytics",
    "excel"
  ];

  criticalSignals.forEach(signal => {
    if (containsPhrase(resumeText, signal) && keywords.includes(signal)) score += 2;
  });

  if (score > 98) score = 98;
  if (score < 45) score = 45;

  return {
    score,
    coverage: Math.round(coverage * 100),
    matched,
    missing,
    job_keywords: keywords,
    notes: `Matched ${matched.length} of ${keywords.length} extracted job keywords.`
  };
}

