function cleanText(value) {
  return String(value ?? "")
    .replace(/[\uFFFE\uFFFF\uFFFC\uFFFD\u0000-\u001F\u007F]/g, " ")
    .replace(/[–—]/g, "-")
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/\s+/g, " ")
    .trim();
}

function lower(value) {
  return cleanText(value).toLowerCase();
}

function ensureArray(value) {
  return Array.isArray(value) ? value : [];
}

function uniqueBy(values, keyFunction) {
  const seen = new Set();
  const output = [];
  ensureArray(values).forEach(value => {
    const key = lower(keyFunction(value));
    if (!key || seen.has(key)) {
      return;
    }
    seen.add(key);
    output.push(value);
  });
  return output;
}

function uniqueList(values) {
  const seen = new Set();
  const output = [];
  ensureArray(values).forEach(value => {
    const cleaned = cleanText(value);
    const key = lower(cleaned);
    if (!cleaned || seen.has(key)) {
      return;
    }
    seen.add(key);
    output.push(cleaned);
  });
  return output;
}

function phraseIn(text, phrase) {
  const cleanedPhrase = lower(phrase);
  if (!cleanedPhrase) {
    return false;
  }
  return lower(text).includes(cleanedPhrase);
}

function splitCommaTerms(value) {
  return String(value || "")
    .split(",")
    .map(cleanText)
    .filter(Boolean);
}

function addCommaTerm(text, term) {
  const base = cleanText(text);
  const cleanedTerm = cleanText(term);
  if (!cleanedTerm) {
    return base;
  }
  if (phraseIn(base, cleanedTerm)) {
    return base;
  }
  return base ? base + ", " + cleanedTerm : cleanedTerm;
}

function getField(key) {
  for (const containerName of aliasContainers) {
    const value = item[containerName]?.[key];
    if (cleanText(value)) {
      return cleanText(value);
    }
  }
  return "";
}

function setField(key, value) {
  const cleaned = cleanText(value);
  aliasContainers.forEach(containerName => {
    item[containerName] = item[containerName] || {};
    item[containerName][key] = cleaned;
  });
