function extractKeywords(job) {
  const text = jobText(job);
  let found = keywordBank.filter(keyword => phraseIn(text, keyword));
  const title = lower(job?.title);
  if (title.includes("training")) {
    found.push("training", "training and development", "new hire orientation", "learning and development", "lms");
  }
  if (title.includes("hr representative")) {
    found.push("hr representative", "employee relations", "hr compliance", "performance management", "manager support", "hrms");
  }
  if (title.includes("hr assistant")) {
    found.push("hr operations", "employee records", "onboarding", "recruiting");
  }
  if (title.includes("benefits")) {
    found.push("benefits", "benefits administration", "benefits communication");
  }
  if (title.includes("payroll")) {
    found.push("employee data", "data accuracy");
  }
  return uniqueList(found);
}

function mappingIsSupported(mapping) {
  return ensureArray(mapping?.evidence).some(evidencePhrase => phraseIn(approvedFactText, evidencePhrase));
}

function keywordMatchesResume(keyword, currentResumeText) {
  if (phraseIn(currentResumeText, keyword)) {
    return true;
  }
  const mapping = keywordMap[keyword];
  if (mapping && mappingIsSupported(mapping) && phraseIn(currentResumeText, mapping.term)) {
    return true;
  }
  return false;
}

function calculate(job) {
  const keywords = extractKeywords(job);
  const currentResumeText = resumeText();
  const matched = [];
  const missing = [];
  keywords.forEach(keyword => {
    if (keywordMatchesResume(keyword, currentResumeText)) {
      matched.push(keyword);
    } else {
      missing.push(keyword);
    }
  });
  if (!keywords.length) {
    return { score: 70, coverage: 0, matched, missing, keywords };
  }
  let score = 50 + Math.round((matched.length / keywords.length) * 42);
  ["human resources", "hr operations", "employee records", "hr documentation", "onboarding", "advanced excel", "excel"].forEach(keyword => {
    if (phraseIn(currentResumeText, keyword)) {
      score += 1;
    }
  });
  return {
    score: Math.min(98, Math.max(50, score)),
    coverage: Math.round((matched.length / keywords.length) * 100),
    matched,
    missing,
    keywords
  };
}

function relevanceScoreForTerm(term, job) {
  const text = jobText(job);
  let score = 0;
  if (phraseIn(text, term)) {
    score += 10;
  }
  Object.entries(keywordMap).forEach(([keyword, mapping]) => {
    if (lower(mapping?.term) === lower(term) && phraseIn(text, keyword)) {
      score += 5;
    }
  });
  return score;
}

function reorderSkills(skillText, job, maximumItems) {
  const terms = uniqueList(splitCommaTerms(skillText));
  return terms
    .map((term, index) => ({
      term,
      index,
      relevance: relevanceScoreForTerm(term, job)
    }))
    .sort((a, b) => {
      if (b.relevance !== a.relevance) {
        return b.relevance - a.relevance;
      }
      return a.index - b.index;
    })
    .slice(0, maximumItems)
    .map(row => row.term)
    .join(", ");
}

function applyRewrite(job, missingKeywords, safeAdded, blockedKeywords) {
  let hrSkills = getField("HR_OPERATIONS_SKILLS");
  let dataSkills = getField("DATA_ANALYTICS_SKILLS");
  let complianceTools = getField("COMPLIANCE_TOOLS");

  missingKeywords.forEach(keyword => {
    const mapping = keywordMap[keyword];
    if (!mapping || !mappingIsSupported(mapping)) {
      blockedKeywords.push(keyword);
      return;
    }
    let currentValue = "";
    if (mapping.field === "HR_OPERATIONS_SKILLS") currentValue = hrSkills;
    if (mapping.field === "DATA_ANALYTICS_SKILLS") currentValue = dataSkills;
    if (mapping.field === "COMPLIANCE_TOOLS") currentValue = complianceTools;

    const updatedValue = addCommaTerm(currentValue, mapping.term);
    if (updatedValue !== currentValue) {
      safeAdded.push({
        keyword,
        added_term: mapping.term,
        target_field: mapping.field
      });
    }
    if (mapping.field === "HR_OPERATIONS_SKILLS") hrSkills = updatedValue;
    if (mapping.field === "DATA_ANALYTICS_SKILLS") dataSkills = updatedValue;
    if (mapping.field === "COMPLIANCE_TOOLS") complianceTools = updatedValue;
  });

  hrSkills = reorderSkills(hrSkills, job, 25);
  dataSkills = reorderSkills(dataSkills, job, 20);
  complianceTools = reorderSkills(complianceTools, job, 15);
  setField("HR_OPERATIONS_SKILLS", hrSkills);
  setField("DATA_ANALYTICS_SKILLS", dataSkills);
  setField("COMPLIANCE_TOOLS", complianceTools);
}

