  history.push({
    round,
    score_before: scoreBefore,
    score_after: after.score,
    missing_before: current.missing.slice(0, 40),
    missing_after: after.missing.slice(0, 40)
  });
  current = after;
  if (after.score === scoreBefore) break;
}

const safeAddedUnique = uniqueBy(safeAdded, row => cleanText(row.keyword) + "|" + cleanText(row.added_term) + "|" + cleanText(row.target_field));
const reviewKeywords = uniqueList([...blockedKeywords, ...current.missing]);

item.ats_safe_keywords_added = safeAddedUnique;
item.ats_keywords_left_for_review = reviewKeywords;
item.ats_rewrite_history = history;
item.ats_keyword_guard_version = "fact_bank_gated_v7.6";

