  resume_status: current.score >= target ? "ats_rewritten_target_met" : "ats_rewritten_manual_review_needed",
  human_review_required: true,
  validation_notes: cleanText((resume.validation_notes || "") + " ATS rewrite completed using fact-bank-supported skills only. Before=" + before.score + ", After=" + current.score + ", Target=" + target + ", Rounds=" + history.length + "."),
  created_at: resume.created_at || now
}));

item.sheet_rows.Tailored_Resumes = item.tailored_resumes;

item.logs.push({
