  cost_control_note: "Only Resume Fact Bank-supported skill terms were added. Unknown JD keywords were not injected.",
  error_detail: ""
});

return [{ json: item }];

const item = $input.first().json || {};
const now = new Date().toISOString();

item.logs = Array.isArray(item.logs) ? item.logs : [];
