function cleanText(value) {
  return String(value || "")
    .replace(/[\uFFFE\uFFFF\uFFFC\uFFFD\u0000-\u001F\u007F]/g, " ")
    .replace(/[–—]/g, "-")
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/\s+/g, " ")
    .trim();
}

function lower(value) {
  return cleanText(value).toLowerCase();
}

function ensureArray(value) {
  return Array.isArray(value) ? value : [];
}

function uniqueBy(arr, keyFn) {
  const seen = new Set();
  const out = [];

  ensureArray(arr).forEach(x => {
    const key = cleanText(keyFn(x));
    if (!key || seen.has(key)) return;
    seen.add(key);
    out.push(x);
  });

  return out;
}

function uniqueList(arr) {
  return [...new Set(ensureArray(arr).map(cleanText).filter(Boolean))];
}

function phraseIn(text, phrase) {
  const t = lower(text);
  const p = lower(phrase);
  if (!p) return false;
  return t.includes(p);
}

function getAllJobs() {
  const jobs = [
    ...ensureArray(item.scored_jobs),
    ...ensureArray(item.sheet_rows?.Scored_Jobs),
    ...ensureArray(item.filtered_jobs),
    ...ensureArray(item.normalized_jobs),
    ...ensureArray(item.raw_jobs),
    ...ensureArray(item.jobs),
    ...ensureArray(item.sheet_rows?.Raw_Jobs)
  ];

  return uniqueBy(jobs, j => j.job_hash || `${j.company}|${j.title}|${j.location}`);
}

function getAllResumes() {
  const resumes = [
    ...ensureArray(item.tailored_resumes),
    ...ensureArray(item.sheet_rows?.Tailored_Resumes)
  ];

  return uniqueBy(resumes, r => r.job_hash || `${r.company}|${r.title}`);
}

function jobText(job) {
  return lower([
    job.title,
    job.company,
    job.location,
    job.employment_type,
    job.description,
    job.job_description,
    Array.isArray(job.responsibilities) ? job.responsibilities.join(" ") : job.responsibilities,
    Array.isArray(job.qualifications) ? job.qualifications.join(" ") : job.qualifications,
    Array.isArray(job.preferred_skills) ? job.preferred_skills.join(" ") : job.preferred_skills,
    job.work_authorization_notes,
    job.cpt_opt_sponsorship_notes,
    job.employer_description,
    job.raw_text,
    typeof job.raw_json === "object" ? JSON.stringify(job.raw_json) : job.raw_json,
    typeof job.source_job === "object" ? JSON.stringify(job.source_job) : job.source_job
  ].join(" "));
}

function resumeText() {
  const containers = [
    item.template_fields,
    item.placeholder_values,
    item.resume_template_fields,
    item.final_resume_fields,
    item.resume_fields,
    item.doc_fields,
    item.google_doc_fields,
    item.replacements
  ];

  const parts = [];

  containers.forEach(obj => {
    if (!obj || typeof obj !== "object") return;
    Object.keys(obj).forEach(k => parts.push(obj[k]));
  });

  const resumes = getAllResumes();
  resumes.forEach(r => {
    [
      r.template_fields,
      r.placeholder_values,
      r.resume_template_fields,
      r.final_resume_fields,
      r.resume_fields,
      r.doc_fields,
      r.google_doc_fields,
      r.replacements
    ].forEach(obj => {
      if (!obj || typeof obj !== "object") return;
      Object.keys(obj).forEach(k => parts.push(obj[k]));
    });
  });

  return lower(parts.join(" "));
}

function extractJobKeywords(job) {
  const text = jobText(job);

  const keywordBank = [
    "human resources",
    "hr",
    "hr representative",
    "hr operations",
    "people operations",
    "employee relations",
    "employee engagement",
    "engagement",
    "site climate",
    "site culture",
    "workplace culture",
    "associate relations",
    "associate programs",
    "internal investigations",
    "investigations",
    "conflict resolution",
    "performance management",
    "performance review",
    "manager coaching",
    "coaching managers",
    "manager support",
    "advocate and counsel",
    "hourly associates",
    "exempt associates",
    "staffing",
    "succession planning",
    "workforce planning",
    "compensation",
    "benefits",
    "benefits communication",
    "benefits administration",
    "employee communications",
    "payroll",
    "hris",
    "hrms",
    "hr systems",
    "databases",
    "employee data",
    "hr data",
    "data analytics",
    "hr reporting",
    "data accuracy",
    "compliance",
    "hr compliance",
    "audit activities",
    "audit readiness",
    "hr policies",
    "policies and procedures",
    "labor law",
    "hr best practices",
    "training",
    "training facilitation",
    "facilitating trainings",
    "interviewing",
    "hiring",
    "terminations",
    "promotions",
    "sexual harassment",
    "onboarding",
    "recruiting",
    "talent acquisition",
    "candidate communication",
    "interview scheduling",
    "pre-employment checks",
    "applicant follow-ups",
    "administrative support",
    "microsoft office",
    "advanced excel",
    "excel",
    "power bi",
    "tableau",
    "ats",
    "hcm",
    "lms",
    "communication",
    "interpersonal skills",
    "confidentiality",
    "attention to detail",
    "organizational skills"
  ];

  let found = keywordBank.filter(k => phraseIn(text, k));

  const title = lower(job.title);

  if (title.includes("hr representative")) {
    found.push("hr representative", "employee relations", "hr compliance", "performance management", "manager support");
  }

  if (title.includes("hr assistant")) {
    found.push("hr operations", "employee records", "administrative support", "onboarding");
  }

  if (title.includes("benefits")) {
    found.push("benefits", "benefits administration", "benefits communication");
  }

  if (title.includes("payroll")) {
    found.push("payroll", "employee data", "data accuracy");
  }

  if (title.includes("recruit") || title.includes("talent acquisition")) {
    found.push("recruiting", "talent acquisition", "candidate communication", "interview scheduling");
  }

  return uniqueList(found);
}

function findJobForResume(resume) {
  const jobs = getAllJobs();
  const hash = cleanText(resume.job_hash);

  return (
    jobs.find(j => cleanText(j.job_hash) === hash) ||
    jobs.find(j => lower(j.company) === lower(resume.company) && lower(j.title) === lower(resume.title)) ||
    jobs[0] ||
    {}
  );
}

function scoreResume(job, resumeFullText) {
  const keywords = extractJobKeywords(job);

  if (!keywords.length) {
    return {
      score: 70,
      coverage: 0,
      matched: [],
      missing: [],
      keywords: [],
      note: "No job keywords extracted. Review parser input."
    };
  }

  const matched = [];
  const missing = [];

  keywords.forEach(k => {
    if (phraseIn(resumeFullText, k)) matched.push(k);
    else missing.push(k);
  });

  const coverage = Math.round((matched.length / keywords.length) * 100);

  let score = 50 + Math.round((matched.length / keywords.length) * 42);

  const critical = [
    "human resources",
    "hr operations",
    "employee records",
    "hr documentation",
    "onboarding",
    "employee relations",
    "hr compliance",
    "benefits",
    "hris",
    "hrms",
    "data analytics",
    "advanced excel",
    "excel"
  ];

  critical.forEach(k => {
    if (keywords.includes(k) && phraseIn(resumeFullText, k)) score += 1;
  });

  if (score > 98) score = 98;
  if (score < 50) score = 50;

  return {
    score,
    coverage,
    matched,
    missing,
    keywords,
    note: `Matched ${matched.length} of ${keywords.length} extracted job keywords. Coverage=${coverage}%.`
  };
}

let resumes = getAllResumes();

if (!resumes.length) {
  const job = getAllJobs()[0] || {};
  resumes = [{
    run_id: item.run_id || "",
    job_hash: job.job_hash || "",
    company: job.company || "",
    title: job.title || "",
    match_score: job.match_score || "",
