    resume_status: "created_by_ats_score_node",
    human_review_required: true,
    validation_notes: "Resume row created because none existed before ATS score.",
    missing_keywords: "",
    created_at: now
  }];
}

const fullResumeText = resumeText();

const updatedResumes = resumes.map(resume => {
  const job = findJobForResume(resume);
  const result = scoreResume(job, fullResumeText);

  return {
    ...resume,
    ats_resume_score: result.score,
    ats_keyword_coverage_pct: result.coverage,
    ats_matched_keywords: result.matched.join(", "),
    ats_job_keywords_extracted: result.keywords.join(", "),
    missing_keywords: result.missing.join(", "),
