    resume_status: resume.resume_status || "ats_scored",
    human_review_required: true,
    validation_notes: cleanText(`${resume.validation_notes || ""} ATS score calculated from full job description and final resume fields. ${result.note}`),
    created_at: resume.created_at || now
  };
});

item.tailored_resumes = updatedResumes;
item.sheet_rows.Tailored_Resumes = updatedResumes;

item.ats_resume_score_summary = {
  success: true,
  node_version: "Calculate ATS Resume Score",
  resumes_scored: updatedResumes.length,
  deduped: true,
  scores: updatedResumes.map(r => ({
