  message: `Calculated ATS score for ${updatedResumes.length} deduped resume(s).`,
  cost_control_note: "Dedupes resume rows and extracts keywords from full job description, responsibilities, qualifications, preferred skills, raw_json, and source_job.",
  error_detail: ""
});

return [{ json: item }];

const item = $input.first().json || {};
const now = new Date().toISOString();

item.logs = Array.isArray(item.logs) ? item.logs : [];

function cleanText(value) {
  if (value === undefined || value === null) return "";
  return String(value).replace(/\s+/g, " ").trim();
}

// Safely hunt down the resume fields no matter where n8n stored them
let sourceFields = item.template_fields || item.final_resume_fields || item.resume_template_fields || {};
if (Object.keys(sourceFields).length === 0 && Array.isArray(item.doc_generation_requests) && item.doc_generation_requests.length > 0) {
  sourceFields = item.doc_generation_requests[0].template_fields || {};
}

// Deep clone to safely manipulate the data
let fields = JSON.parse(JSON.stringify(sourceFields));

function calculateLength(f) {
  let total = 0;
  Object.values(f).forEach(val => {
    total += cleanText(val).length;
  });
  return total;
}

let currentLength = calculateLength(fields);
const SAFE_MAX_CHARS = 3800; 
let reductionLog = [];

// TRIM LEVEL 1: Empty Project Bullets
if (currentLength > SAFE_MAX_CHARS) {
  if (fields.PROJECT_1_BULLET_3) { fields.PROJECT_1_BULLET_3 = ""; reductionLog.push("Cut Project 1 Bullet 3"); }
  if (fields.PROJECT_2_BULLET_3) { fields.PROJECT_2_BULLET_3 = ""; reductionLog.push("Cut Project 2 Bullet 3"); }
  currentLength = calculateLength(fields);
}

// TRIM LEVEL 2: Cap Skills
if (currentLength > SAFE_MAX_CHARS) {
  const capSkills = (str, limit) => cleanText(str).split(",").map(s=>s.trim()).filter(Boolean).slice(0, limit).join(", ");

  if (fields.HR_OPERATIONS_SKILLS) { fields.HR_OPERATIONS_SKILLS = capSkills(fields.HR_OPERATIONS_SKILLS, 12); reductionLog.push("Capped HR Skills"); }
  if (fields.DATA_ANALYTICS_SKILLS) { fields.DATA_ANALYTICS_SKILLS = capSkills(fields.DATA_ANALYTICS_SKILLS, 10); reductionLog.push("Capped Data Skills"); }
  if (fields.COMPLIANCE_TOOLS) { fields.COMPLIANCE_TOOLS = capSkills(fields.COMPLIANCE_TOOLS, 6); reductionLog.push("Capped Compliance Tools"); }
  currentLength = calculateLength(fields);
}

// TRIM LEVEL 3: Drop 5th Experience Bullets
if (currentLength > SAFE_MAX_CHARS) {
  if (fields.COMPANY_1_BULLET_5) { fields.COMPANY_1_BULLET_5 = ""; reductionLog.push("Cut Company 1 Bullet 5"); }
  if (fields.COMPANY_2_BULLET_5) { fields.COMPANY_2_BULLET_5 = ""; reductionLog.push("Cut Company 2 Bullet 5"); }
  currentLength = calculateLength(fields);
}

// Apply the trimmed fields back to all required payload containers
[
  "template_fields", "placeholder_values", "resume_template_fields", 
  "final_resume_fields", "resume_fields", "doc_fields", 
  "google_doc_fields", "replacements"
].forEach(container => {
  if (item[container]) {
    Object.keys(fields).forEach(k => {
      item[container][k] = fields[k];
    });
  }
});

// Patch the fields into the tailored_resumes array
if (Array.isArray(item.tailored_resumes)) {
  item.tailored_resumes.forEach(r => {
    if (r.template_fields) {
       Object.keys(fields).forEach(k => { r.template_fields[k] = fields[k]; });
    }
  });
}

item.logs.push({
  run_id: item.run_id || "", timestamp: now, node_name: "Strict One-Page Length Enforcer",
  status: reductionLog.length > 0 ? "warning" : "success",
  message: reductionLog.length > 0 ? `Trimmed to fit 1 page: ${reductionLog.join(", ")}` : `Length safe (${currentLength} chars).`,
  cost_control_note: "Guaranteed 1-page physical layout.", error_detail: ""
});

item.resume_length_stats = { final_char_count: currentLength, safe_max_chars: SAFE_MAX_CHARS, reductions_applied: reductionLog };

return [{ json: item }];
